const aluCases=[['2.1','00','xxxxxx','ADD','0','0','0','10'],['2.2','01','xxxxxx','SUB','0','1','1','10'],['2.3','10','100000','ADD','0','0','0','10'],['2.4','10','100010','SUB','0','1','1','10'],['2.5','10','100100','AND','0','0','x','00'],['2.6','10','100101','OR','0','0','x','01'],['2.7','10','100111','NOR','1','1','x','00'],['2.8','10','101010','SLT','0','1','1','11']];
function aluWidget(){let q=aluCases[model.alu];return `<div class="simulator"><div class="simulator-title"><b>ALU CONTROL EXPLORER</b><span>ตารางที่ 1</span></div><div class="step-buttons wrap">${aluCases.map((r,i)=>`<button class="chip ${model.alu===i?'active':''}" data-action="alu" data-value="${i}">${r[0]} ${r[3]}</button>`).join('')}</div><div class="sim-stage"><div class="mini-label">ALUOp ${q[1]} · Funct ${q[2]} · Goal ${q[3]}</div><div class="signal-grid">${['Ainv','Binv','CarryIn','Operation'].map((f,i)=>`<div class="signal-card ${q[i+4]==='1'?'on':''}"><small>${f}</small><b>${q[i+4]}</b></div>`).join('')}</div></div><p class="sim-explanation">${({ADD:'Adder รับ A และ B ตามเดิม ไม่ต้องกลับบิต',SUB:'ใช้ A + NOT(B) + 1 จึงเปิด Binv และ CarryIn',AND:'Operation=00 เลือก AND จากวงจรย่อย',OR:'Operation=01 เลือก OR จากวงจรย่อย',NOR:'ใช้กฎ De Morgan: NOT(A OR B) = NOT(A) AND NOT(B)',SLT:'ใช้การลบ A−B และส่ง Set ที่แก้ signed overflow แล้วไปยัง LESS ของบิตต่ำสุด'})[q[3]]}</p></div>`}
