const quizzes={
1:[{q:'Signed 4-bit: 0101 + 0110 ได้ Result และ Overflow อะไร?',choices:['1011, True','1011, False','0111, True'],correct:0,why:'5+6=11 เกินช่วง Signed 4-bit (−8 ถึง 7) จึง Overflow แม้ Result 4-bit เป็น 1011'},{q:'Signed 4-bit: 1001 + 0011 ได้เท่าไร?',choices:['1100, False','1100, True','1010, False'],correct:0,why:'−7+3=−4 ซึ่งเก็บได้ใน Signed 4-bit ในรูป 1100'}],
2:[{q:'SUB ต้องตั้ง Binv / CarryIn อย่างไร?',choices:['0/0','1/0','1/1'],correct:2,why:'A−B = A+NOT(B)+1 ต้องกลับบิต B และบวก 1'},{q:'NOR ใช้ Ainv, Binv, Operation ชุดไหน?',choices:['0,0,01','1,1,00','1,0,10'],correct:1,why:'กฎ De Morgan: NOT(A OR B) = NOT(A) AND NOT(B)'}],
3:[{q:'lw State 1: ALUSrcA และ ALUSrcB เป็นค่าอะไร?',choices:['0,01','1,10','1,00'],correct:1,why:'คำนวณ Register[rs] + SignExt(Immediate)'},{q:'beq State 2 เปิด Control ใดเพื่อเปลี่ยน PC แบบมีเงื่อนไข?',choices:['PCWrite','PCWriteCond','RegWrite'],correct:1,why:'เปรียบเทียบ Register ด้วย ALU ลบ แล้วใช้ PCWriteCond ร่วมกับ Zero'}],
4:[{q:'srl $t0,$t1,3 อ่านข้อมูลจาก Field ใด?',choices:['rs','rt','rd'],correct:1,why:'คำสั่ง SRL ใช้ rt เป็นต้นทาง และ rd เป็นปลายทาง'},{q:'Shift right 13 เปิด MUX ใด?',choices:['s0, s2, s3','s1, s2, s4','s3, s4'],correct:0,why:'13=8+4+1 จึงเปิด s3,s2,s0'}],
5:[{q:'lw ตามด้วย addi ที่ต้องใช้ผล lw ทันทีคือ Hazard ใด?',choices:['Structural','Load-Use','Control'],correct:1,why:'ข้อมูล Memory เพิ่งพร้อมหลัง MEM Clock 4 แต่ addi ต้องการใน EX Clock 4'},{q:'Branch Prediction ใช้บรรเทา Hazard ประเภทใด?',choices:['Control','RAW','Structural'],correct:0,why:'ทำนาย Taken/Not Taken เพื่อหลีกเลี่ยงรอผล Branch ทุกครั้ง'}],
6:[{q:'Control กลุ่ม M ไปถึง MEM ผ่าน Register ใด?',choices:['IF/ID','EX/MEM','Register File'],correct:1,why:'Main Control สร้างที่ ID แล้ว M Controls ผ่าน ID/EX และ EX/MEM ก่อนถูกใช้ที่ MEM'},{q:'ใน Clock 4 lw อยู่ MEM แต่ sw อยู่ ID, MemRead ของ lw มาจากไหน?',choices:['Main Control ปัจจุบัน','EX/MEM ของ lw','Forwarding Unit'],correct:1,why:'เป็น Control ของ lw ที่ถูกสร้างไว้ก่อนแล้วส่งต่อมากับ Instruction ผ่าน Pipeline Registers'}]
};
function practice(n){let q=quizzes[n]||[],c=chapters[n-1];return `<div class="eyebrow">PRACTICE LAB / CHAPTER ${String(n).padStart(2,'0')}</div><h1 class="hero-title">${c.title}</h1><p class="hero-lede">ลองตอบจากความเข้าใจ แล้วดูเหตุผลทันที หากไม่แน่ใจสามารถกลับไปอ่านบทเรียนได้โดยไม่เสียคำตอบเดิม</p><div class="view-tabs"><a href="#/study/${n}">▤ บทเรียน</a><a class="active" href="#/practice/${n}">✎ ฝึกทำ</a></div>${q.map((item,i)=>{let key=`${n}-${i}`,chosen=model.answers[key];return `<div class="quiz-card"><div class="quiz-number">QUESTION ${i+1} / ${q.length}</div><h3>${item.q}</h3>${item.choices.map((choice,j)=>`<button class="quiz-option ${chosen===j?'selected':''} ${chosen!==undefined&&j===item.correct?'correct':''} ${chosen===j&&chosen!==item.correct?'wrong':''}" data-action="answer" data-key="${key}" data-value="${j}"><span class="letter">${String.fromCharCode(65+j)}</span><span>${choice}</span></button>`).join('')}${chosen!==undefined?`<div class="quiz-feedback ${chosen===item.correct?'ok':'no'}"><strong>${chosen===item.correct?'✓ ถูกต้อง':'ลองทบทวนอีกครั้ง'}</strong><div>${item.why}</div></div>`:''}</div>`}).join('')}<div class="lesson-nav"><a href="#/study/${n}">← กลับไปอ่านบทเรียน</a><a href="#/practice/${n<6?n+1:1}">ฝึกข้อ ${n<6?n+1:1} →</a></div>`}
function library(){return `<div class="eyebrow">EXAM COLLECTION</div><h1 class="hero-title">Computer Architecture</h1><p class="hero-lede">เรียนตามข้อสอบจริงแบบ Interactive Textbook: อ่าน Concept ผ่าน Visual, ทดลองอุปกรณ์ และกลับมาฝึกทำโจทย์ได้ในหน้าแยก</p><div class="library-heading"><div><strong>FE2019b</strong><span>6 Chapters · 198322 · Mid/Final Exam Study</span></div>${badge(`${model.completed.length}/6 เรียนแล้ว`)}</div><div class="library-grid">${chapters.map(c=>`<a class="library-card" href="#/study/${c.id}"><div class="lib-top"><span>CHAPTER ${String(c.id).padStart(2,'0')}</span>${model.completed.includes(c.id)?'<span class="good">✓ เรียนแล้ว</span>':''}</div><h3>${c.title}</h3><p>${c.subtitle}</p><div class="lib-bottom">เปิดบทเรียน <span>↗</span></div></a>`).join('')}</div>${note('Reading-first','เนื้อหาทั้งหกข้อแบ่ง Concept, Diagram, Worked Example และเฉลยครบ การ์ดและ UI ใช้เพื่ออธิบายกลไก ไม่ใช่แทนเหตุผลของบทเรียน')}`}
function review(){let count=Object.values(model.answers).length,total=Object.values(quizzes).reduce((sum,arr)=>sum+arr.length,0);return `<div class="eyebrow">STUDY PROGRESS</div><h1 class="hero-title">Review & Progress</h1><p class="hero-lede">เก็บความคืบหน้าใน Browser ของเครื่องนี้โดยไม่ต้องมีบัญชี เพื่อกลับมาทวนเฉพาะข้อที่ยังไม่แม่น</p><div class="review-stats"><div><small>CHAPTERS COMPLETED</small><strong>${model.completed.length} / 6</strong></div><div><small>PRACTICE ANSWERED</small><strong>${count} / ${total}</strong></div></div>${table(['บท','บทเรียน','ความคืบหน้า','ย้อนอ่าน'],chapters.map(c=>[c.id,c.title,model.completed.includes(c.id)?'<span class="good">✓ เรียนแล้ว</span>':'ยังไม่ได้ทำเครื่องหมาย',`<a href="#/study/${c.id}">เปิดบทเรียน ↗</a>`]))}${note('Privacy','สถานะบันทึกเฉพาะใน localStorage ของเบราว์เซอร์ หากเปิดในเครื่องอื่นจะยังไม่ซิงก์ข้อมูล')}`}
function parseRoute(){let match=location.hash.match(/^#\/(study|practice)\/([1-6])\/?$/);if(match)return {mode:match[1],n:Number(match[2])};if(location.hash==='#/review')return {mode:'review',n:1};return {mode:'library',n:1}}
function updateTheme(){let theme=model.theme==='auto'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):model.theme;document.documentElement.setAttribute('data-theme',theme);document.documentElement.style.setProperty('--font-scale',model.font);$('#theme-icon').textContent=theme==='dark'?'☾':'☀';$('#theme-text').textContent=theme==='dark'?'Dark':'Light';let meta=$('meta[name="theme-color"]');if(meta)meta.content=theme==='dark'?'#0f1621':'#f7f9fc';}
function renderNav(){const r=parseRoute();$('#chapter-nav').innerHTML=chapters.map(c=>`<a href="#/study/${c.id}" class="chapter-link ${r.mode==='study'&&r.n===c.id?'active':''}"><span class="chapter-number">${String(c.id).padStart(2,'0')}</span><span class="chapter-info"><strong>${c.title}</strong><small>${c.subtitle}</small></span>${model.completed.includes(c.id)?'<span class="chapter-done">✓</span>':''}</a>`).join('')+`<div class="nav-separator"></div><a href="#/library" class="chapter-link ${r.mode==='library'?'active':''}"><span class="chapter-number">⌂</span><span class="chapter-info"><strong>Exam Library</strong><small>รายการบทเรียน</small></span></a><a href="#/review" class="chapter-link ${r.mode==='review'?'active':''}"><span class="chapter-number">◷</span><span class="chapter-info"><strong>Progress</strong><small>สถานะและผลแบบฝึกหัด</small></span></a>`;
let percent=Math.round(model.completed.length/6*100);$('#completed-short').textContent=`${model.completed.length}/6`;$('#progress-sidebar').textContent=`${percent}%`;$('#progress-fill').style.width=`${percent}%`;}
function outline(){let list=[...document.querySelectorAll('#page .lesson-section')];$('#outline').innerHTML=list.map(s=>`<button type="button" data-action="scroll" data-value="${s.id}" class="outline-link">${esc(s.querySelector('h2')?.textContent||'')}</button>`).join('');}
function render(){const r=parseRoute(),page=$('#page');const n=r.n;page.innerHTML=r.mode==='study'?([lesson1,lesson2,lesson3,lesson4,lesson5,lesson6][n-1]()).concat(`<div class="view-tabs bottom"><a class="active" href="#/study/${n}">▤ อ่านบทเรียน</a><a href="#/practice/${n}">✎ ฝึกทำ</a></div>`):r.mode==='practice'?practice(n):r.mode==='review'?review():library();$('#header-label').textContent=r.mode==='study'?chapters[n-1].title:r.mode==='practice'?'Practice Lab':r.mode==='review'?'Progress':'Exam Library';renderNav();outline();updateReadingProgress();document.title=`${r.mode==='study'?chapters[n-1].title:r.mode==='practice'?'Practice':'Library'} · ComArc Exam Lab`;}
function updateReadingProgress(){let root=$('#page');let start=root.getBoundingClientRect().top+scrollY;let range=Math.max(1,root.offsetHeight-innerHeight+90);let pct=Math.max(0,Math.min(100,(scrollY-start+78)/range*100));$('#read-progress-fill').style.width=pct+'%';}
function rerenderKeepScroll(){const y=scrollY;render();window.scrollTo({top:y,behavior:'instant'});}
function onAction(action,el){let v=el.dataset.value;if(action==='scroll'){document.getElementById(v)?.scrollIntoView({behavior:'smooth',block:'start'});return}if(action==='zoom'){const content=el.closest('.diagram-card')?.cloneNode(true);if(content){content.querySelectorAll('.figure-zoom').forEach(x=>x.remove());$('#figure-modal-content').replaceChildren(content);$('#figure-modal').hidden=false}return}switch(action){
case 'arith':model.arithmetic=Number(v);break;
case 'alu':model.alu=Number(v);break;
case 'command':model.command=v;if(v==='j'&&model.state===2)model.state=1;break;
case 'state':model.state=Number(v);break;
case 'next-state':model.state=Number(currentState().b[7]);break;
case 'shiftdata':model.shifterData=Number(v);break;
case 'shamt':model.shamt=Number(v);break;
case 'hazard':model.hazard=v;break;
case 'pclock':model.pipeClock=Number(v);break;
case 'pipeprev':model.pipeClock=Math.max(1,model.pipeClock-1);break;
case 'pipenext':model.pipeClock=Math.min(9,model.pipeClock+1);break;
case 'clockprev':model.clock=Math.max(1,model.clock-1);break;
case 'clocknext':model.clock=Math.min(7,model.clock+1);break;
case 'clockreset':model.clock=1;model.focus=0;break;
case 'focus':model.focus=Number(v);break;
case 'complete':{let n=Number(v);model.completed=model.completed.includes(n)?model.completed.filter(x=>x!==n):[...model.completed,n].sort();persist();break;}
case 'answer':model.answers[el.dataset.key]=Number(v);persist();break;
default:return;}rerenderKeepScroll();}
function closeDrawer(){$('#sidebar').classList.remove('open');$('#overlay').hidden=true;}
function init(){updateTheme();if(!location.hash)history.replaceState(null,'','#/study/1');render();addEventListener('hashchange',()=>{closeDrawer();render();window.scrollTo(0,0)});document.addEventListener('click',event=>{const action=event.target.closest('[data-action]');if(action){if(action.matches('input[type=range]'))return;event.preventDefault();if(!action.disabled)onAction(action.dataset.action,action);return;}const link=event.target.closest('a[href^="#"]');if(link&&/^#(?!\/)/.test(link.getAttribute('href'))){return;}if(link&&link.closest('#sidebar'))closeDrawer()});document.addEventListener('change',event=>{const el=event.target;if(el.matches('[data-action="shamt"], [data-action="pclock"]'))onAction(el.dataset.action,el)});$('#theme-toggle').addEventListener('click',()=>{let actual=document.documentElement.getAttribute('data-theme');model.theme=actual==='dark'?'light':'dark';persist();updateTheme()});$('#font-less').addEventListener('click',()=>{model.font=Math.max(.85,Math.round((model.font-.05)*100)/100);persist();updateTheme()});$('#font-more').addEventListener('click',()=>{model.font=Math.min(1.3,Math.round((model.font+.05)*100)/100);persist();updateTheme()});$('#menu-open').addEventListener('click',()=>{$('#sidebar').classList.add('open');$('#overlay').hidden=false});$('#overlay').addEventListener('click',closeDrawer);$('#figure-close').addEventListener('click',()=>{$('#figure-modal').hidden=true});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#figure-modal').hidden=true;closeDrawer()}});$('#collection').addEventListener('click',()=>{location.hash='#/library';closeDrawer()});addEventListener('scroll',updateReadingProgress,{passive:true});matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(model.theme==='auto')updateTheme()});}
init();